import { FastifyInstance } from 'fastify';
import { UptimeService } from './uptime.service';

export async function uptimeRoutes(fastify: FastifyInstance): Promise<void> {
  fastify.get('/uptime', async (request, reply) => {
    try {
      const uptimeService = new UptimeService();
      const status = uptimeService.getUptime();
      return reply.status(200).send(status);
    } catch (error) {
      request.log.error(error);
      return reply.status(500).send({ error: 'Internal Server Error' });
    }
  });
}
import { IUptimeService } from './uptime.service.interface';
import { UptimeStatus } from './uptime.model';

export class UptimeService implements IUptimeService {
  getUptime(): UptimeStatus {
    return { uptimeSeconds: Math.floor(process.uptime()) };
  }
}
import { UptimeStatus } from './uptime.model';

export interface IUptimeService {
  getUptime(): UptimeStatus;
}
export { UptimeStatus } from './uptime.model';
export { IUptimeService } from './uptime.service.interface';
export { UptimeService } from './uptime.service';
export { uptimeRoutes } from './uptime.routes';
